CREATE OR REPLACE FUNCTION public.under_building(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  -- cellar: said first, as `corner_under_building` says it.
  select case when (cellar_at(p_world, p_x, p_y)).world_id is not null
